-- Team captain permissions and tournament applications. Idempotent; preserves existing records.
BEGIN;
ALTER TABLE public.mvp_tournaments ADD COLUMN IF NOT EXISTS allow_captain_registration boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS public.mvp_team_captains (team_id bigint PRIMARY KEY REFERENCES public.teams(id) ON DELETE CASCADE,user_id uuid NOT NULL UNIQUE REFERENCES public.mvp_auth_users(id) ON DELETE CASCADE,assigned_by uuid REFERENCES public.mvp_auth_users(id) ON DELETE SET NULL,assigned_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.mvp_tournament_applications (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tournament_id bigint NOT NULL REFERENCES public.mvp_tournaments(id) ON DELETE CASCADE,team_id bigint NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,captain_user_id uuid NOT NULL REFERENCES public.mvp_auth_users(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid REFERENCES public.mvp_auth_users(id) ON DELETE SET NULL,admin_note text NOT NULL DEFAULT '',UNIQUE(tournament_id,team_id));
CREATE INDEX IF NOT EXISTS mvp_tournament_applications_status_idx ON public.mvp_tournament_applications(status,created_at DESC);
CREATE OR REPLACE FUNCTION public.mvp_captain_save_team(p_team_id bigint,p_name text,p_tag text,p_players text,p_logo text,p_player_photos jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $fn$
DECLARE v_team public.teams; v_item text; v_photo text; v_pos integer:=0; v_roster text[]:=ARRAY[]::text[];
BEGIN
 IF length(btrim(coalesce(p_name,'')))<2 OR length(p_name)>80 THEN RAISE EXCEPTION 'Некорректное название команды'; END IF;
 IF jsonb_typeof(coalesce(p_player_photos,'[]'::jsonb))<>'array' OR jsonb_array_length(coalesce(p_player_photos,'[]'::jsonb))>5 THEN RAISE EXCEPTION 'Некорректные фотографии состава'; END IF;
 FOR v_item IN SELECT btrim(x) FROM regexp_split_to_table(coalesce(p_players,''),'[,;\n\r·•|]+') x WHERE btrim(x)<>'' LOOP
   IF length(v_item)>32 THEN RAISE EXCEPTION 'Слишком длинный ник игрока'; END IF;
   IF lower(v_item)=ANY(SELECT lower(unnest(v_roster))) THEN RAISE EXCEPTION 'Повторяющийся игрок в составе'; END IF;
   v_roster:=array_append(v_roster,v_item);v_pos:=v_pos+1;IF v_pos>5 THEN RAISE EXCEPTION 'Максимум пять игроков';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.cs2_players p WHERE lower(p.nickname)=ANY(SELECT lower(unnest(v_roster))) AND p.team_id IS NOT NULL AND p.team_id<>p_team_id) THEN RAISE EXCEPTION 'Игрок уже состоит в другой команде';END IF;
 UPDATE public.teams SET name=btrim(p_name),tag=left(coalesce(p_tag,''),12),players=coalesce(p_players,''),logo=coalesce(p_logo,''),player_photos=coalesce(p_player_photos,'[]'::jsonb) WHERE id=p_team_id RETURNING * INTO v_team;
 IF NOT FOUND THEN RAISE EXCEPTION 'Команда не найдена';END IF;
 UPDATE public.cs2_players p SET team_id=NULL WHERE p.team_id=p_team_id AND NOT(lower(p.nickname)=ANY(SELECT lower(unnest(v_roster))));
 v_pos:=0;
 FOR v_item IN SELECT unnest(v_roster) LOOP
   v_photo:=coalesce(p_player_photos->>v_pos,'');
   IF EXISTS(SELECT 1 FROM public.cs2_players p WHERE lower(p.nickname)=lower(v_item)) THEN UPDATE public.cs2_players SET team_id=p_team_id,photo_url=v_photo WHERE id=(SELECT id FROM public.cs2_players WHERE lower(nickname)=lower(v_item) ORDER BY id LIMIT 1);
   ELSE INSERT INTO public.cs2_players(nickname,photo_url,team_id) VALUES(v_item,v_photo,p_team_id);END IF;
   v_pos:=v_pos+1;
 END LOOP;
 RETURN jsonb_build_object('id',v_team.id,'name',v_team.name,'tag',v_team.tag,'players',v_team.players,'logo',v_team.logo,'player_photos',v_team.player_photos);
END;$fn$;
REVOKE ALL ON FUNCTION public.mvp_captain_save_team(bigint,text,text,text,text,jsonb) FROM PUBLIC;
REVOKE ALL ON public.mvp_team_captains FROM PUBLIC;
REVOKE ALL ON public.mvp_tournament_applications FROM PUBLIC;
COMMIT;